import asyncio
import logging
from typing import Optional
from google import genai
from google.genai import types

from schemas import ParsedOrder
import config

logger = logging.getLogger(__name__)
client = genai.Client(api_key=config.GEMINI_API_KEY, http_options=types.HttpOptions(retry_options=types.HttpRetryOptions(attempts=1)))

SYSTEM_INSTRUCTION = """
Используй следующие правила обработки данных заказа:
Поле shop_name содержит название магазина в формате "(полное название магазина) - (адрес магазина)". Полное название магазина всегда указывается дословно, а адрес магазина кратко без указания типа улицы в формате "(название улицы/переулка/проспекта/др.), (номер дома)"
Поле time_interval содержит временной интервал заказа в формате "(начало временного интервала)-(конец временного интервага)" или "к (точное время)" или "в ближайшее время". Время в временных интервалах и точном времени указывается в формате "H:MM" или "HH:MM", если HH>=10
Поле address содержит полный адрес доставки в формате "(краткий тип улицы). (название улицы/переулка/проспекта/др.) (номер дома), (дополнительная информация, если таковая имеется)" для адресов Минска, или предварительно указав агрогородок, город, посёлок, деревню перед точным адресом, если адрес находится вне Минска. Дополнительная информация может быть любым уточнением и часто указывается в свободном формате, но предпочтительно указывать данные по увеличению точности, например: "пр. Дзержинского 123, подъезд 4, этаж 3, кв. 254, код домофона #197328#", или "п. Привольный, ул. Мира 2Бк1, офисное здание R Group", или "ул. Чюрлёниса 3, общежитие №8, этаж 10, комн. 1008", или "пр. Независимости 64к5 (больница №1), гинекологический корпус, этаж 2, палата 230"
Поле driver_details содержит любую информацию, необходимую доставщику, в свободном формате, например о том, что домофон не работает, о необходимости предварительно позвонить, о способах подъезда, об информации о заказчике, о способах передачи или оставления заказа, о предпочитаемом времени получения заказа, и/или другом.
Поле order_contents содержит информацию о товаре доставки. Информация может содержать детали о габаритах товара, количестве товаров, условиях перевозки, и/или другом. Если информация занимает более 50 слов, то необходимо сократить достаточно для сохранения читаемости доставщиком.
Поле payment_status отображает информацию об оплате. Если товар заказан на платформе flowwow, информация узнаваемая по пометкам "флоу, флау, флоувау", "флаувау" и другим вариациям, то в первую очередь указывается "Флау". Формат оплаты краткий, например, для неоплаченных товаров указывается "К оплате: нал (полная стоимость)р" - если указана оплата наличными, или "К оплате: (полная стоимость)р ТЕРМИНАЛ" - если указана безналичная оплата, или "К оплате: (полная стоимость)р" - если тип оплаты не указан явно. (полная стоимость) подразумевает рубли и копейки, причём если копеек нет, то указывается только количество рублей, а если копейки есть, то указывается их количество с двумя знаками, например, "70р", или "134,50р", или "740,99р".
Поле is_valid_order является проверкой на действительность заказа по косвенным данным. На ряду с заказами в выше указанном формате может быть отправлено обычное текстовое сообщение без намерения сообщить информацию о готовом зазаке, например, обычное сообщение из диалога, или уведомление, или пометка, или намерение отправить заявку без её явного отправления в доставку (в таком случае будут вопросы к администратору по типу "сможем принять?" или "возможно ли перевезти такие габариты?" или "успеете к назначенному интервалу?") - в таких случаях сообщение не является готовой к обработке заявкой, и поля выше могут быть None, и поле is_valid_order должно быть false. Если заявка действительна, то is_valid_order должно быть true.
"""

async def parse_order_from_text(raw_text: str) -> Optional[ParsedOrder]:
    models_cycle = ["gemini-3.8-flash", "gemini-3.5-flash-lite", "gemini-3.5-flash-lite", "gemini-3.5-flash-lite", "gemini-3.1-flash-lite"]

    for model in models_cycle:
        try:
            interaction = await client.aio.interactions.create(
                model=model,
                input=f"Предоставь полную информацию о следующем заказе: {raw_text}. {SYSTEM_INSTRUCTION}",
                generation_config={"thinking_level": "low"},
                response_format={
                    "type": "text",
                    "mime_type": "application/json",
                    "schema": ParsedOrder.model_json_schema()
                },
                timeout=15
            )

            return ParsedOrder.model_validate_json(interaction.output_text)

        except Exception as err:
            logger.warning(f"Model {model} failed: {err}, trying next...")
            await asyncio.sleep(1)

    logger.error("Unable to parse order from text")
    return None